// Private, explicit Mac dogfood. Not a benchmark, repository acceptance or release.
// Run: node work-orders/opencode-local-orchestration-v1/live-smoke.mjs --live-local [--allow-cold-start]
// Only JSON data generated by the model is inspected. Generated programs never run.
import assert from 'node:assert/strict';
import { mkdtemp, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { work } from '~/.config/opencode/tools/nisi_local.ts';

if (!process.argv.includes('--live-local') || process.argv.slice(2).some(arg =>
  !['--live-local', '--allow-cold-start'].includes(arg))) {
  throw new Error('Explicit --live-local required; optional --allow-cold-start only. No other routes.');
}
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const directory = await mkdtemp(path.join(root, '.build/opencode-local-smoke-'));
const task = { taskId: 'opencode.retry-config', mode: 'edit', language: 'json',
  allowedFiles: ['retry-config.json'], protectedFiles: [], protectedSnapshots: {},
  acceptanceCriteria: ['Return retry-config.json only: a JSON object with exactly maxRetries=3, retryDelayMs=250, backoff="exponential".'],
  policy: { repairBudget: 0, totalDeadlineMs: 120000, requiredReviewers: 1, requireReportStore: false } };
const started = performance.now();
const result = JSON.parse(await work.execute({ runId: path.basename(directory), taskJson: JSON.stringify(task),
  mode: 'draft_review', authorModel: 'qwen/qwen3.8-27b', reviewerModel: 'qwen/qwen3.8-27b',
  timeoutMs: 120000, maxOutputTokens: 2048, allowColdStart: process.argv.includes('--allow-cold-start') },
  { abort: new AbortController().signal }));
const tests = [];
for (const [name, check] of [
  ['response validated', () => assert.equal(result.status, 'RESPONSE_VALIDATED')],
  ['exact candidate file', () => assert.deepEqual(result.candidate.files.map(file => file.path), ['retry-config.json'])],
  ['exact configuration values', () => assert.deepEqual(JSON.parse(result.candidate.files[0].content), {maxRetries: 3, retryDelayMs: 250, backoff: 'exponential'})],
  ['same model is self-review', () => assert.equal(result.reviewRelationship, 'self_review')],
  ['no independent reviewer credit', () => assert.equal(result.independentReviewerCount, 0)],
  ['no acceptance laundering', () => { assert.equal(result.accepted, false); assert.equal(result.tests, 'NOT_RUN'); }],
]) {
  try { check(); tests.push({ name, status: 'PASS' }); }
  catch { tests.push({ name, status: 'FAIL' }); }
}
const evidence = { kind: 'nisi.development-smoke.v1', scope: 'synthetic-json-data-only',
  status: tests.every(test => test.status === 'PASS') ? 'PASS' : 'FAIL',
  createdAt: new Date().toISOString(), elapsedMs: Math.round(performance.now() - started),
  task, tests, advisory: result, automaticLearning: false,
  benchmarkComparison: 'NOT_RUN', publication: 'NOT_AUTHORIZED' };
await writeFile(path.join(directory, 'evidence.json'), JSON.stringify(evidence, null, 2) + '\n', {mode: 0o600, flag: 'wx'});
console.log(JSON.stringify({ status: evidence.status, evidence: path.join(directory, 'evidence.json'),
  checks: `${tests.filter(t => t.status === 'PASS').length}/${tests.length}`, elapsedMs: evidence.elapsedMs,
  code: result.code, models: result.receipts?.map(r => ({requested: r.requestedModel, reported: r.reportedModel, usage: r.usage})),
  evidenceSha256: createHash('sha256').update(JSON.stringify(evidence)).digest('hex') }, null, 2));
if (evidence.status !== 'PASS') process.exitCode = 1;
